const { accessSync } = await import('node:fs');
const markdownPath = process.env.MARKDOWN_PATH;
if (!markdownPath) { throw new Error('MARKDOWN_PATH not provided'); }
try { accessSync(markdownPath); } catch (e) { throw new Error('Markdown file not accessible: ' + e.message); }
globalThis.markdownPath = markdownPath;

const mod = await import('markdown-pdf');
const markdownpdf = mod.default || mod;
const { join } = await import('node:path');
const { tmpdir } = await import('node:os');
const pdfPath = join(tmpdir(), 'markdown-' + Date.now() + '.pdf');
await new Promise((resolve, reject) => {
  markdownpdf()
    .from(globalThis.markdownPath)
    .to(pdfPath, (err) => {
      if (err) reject(err);
      else resolve();
    });
});
globalThis.pdfPath = pdfPath;
